import React, { useEffect, useState, useMemo, useCallback } from 'react';
import {
  Heart,
  ThumbsUp,
  ThumbsDown,
  Sliders,
  X,
  ChevronDown,
  ChevronRight,
  Gift,
  Loader2,
  Package,
  ShoppingCart,
  Tag
} from 'lucide-react';

// Utility Funktion für Debouncing
const debounce = (func, wait) => {
  let timeout;
  return (...args) => {
    clearTimeout(timeout);
    timeout = setTimeout(() => func(...args), wait);
  };
};

// Alert Komponente
const Alert = React.memo(({ variant = 'error', children }) => {
  const styles = useMemo(() => ({
    bgColor: variant === 'error' ? 'bg-red-100' : 'bg-teal-100',
    textColor: variant === 'error' ? 'text-red-900' : 'text-teal-900'
  }), [variant]);

  return (
    <div className={`${styles.bgColor} ${styles.textColor} p-4 rounded-lg border border-current/20 shadow-sm my-6 animate-fade-in`}>
      {children}
    </div>
  );
});

// ProductCard Komponente
const ProductCard = React.memo(({ product, onLike, onDislike, likedProducts = [] }) => {
  const imageUrl = useMemo(() => {
    if (!product.image) return '/placeholder-gift.jpg';
    if (typeof product.image === 'string') {
      if (product.image.includes('src=')) {
        const match = product.image.match(/src="([^"]+)"/);
        return match ? match[1] : '/placeholder-gift.jpg';
      }
      if (product.image.startsWith('http')) return product.image;
    }
    return product.image;
  }, [product.image]);

  const handleImageError = useCallback((e) => {
    e.currentTarget.src = '/placeholder-gift.jpg';
  }, []);

  // Button Text Logic: Verwende product.add_to_cart_text, falls vorhanden, sonst den Standardtext.
  const shopButtonText = product.add_to_cart_text || 'Zum Shop ➜';

  return (
    <div className="bg-white rounded-xl shadow-sm overflow-hidden group transform transition-all duration-300 hover:shadow-lg hover:-translate-y-1">
      <div className="relative">
        <a href={product.url} className="block">
          <img
            src={imageUrl}
            alt={product.name}
            loading="lazy"
            decoding="async"
            className="w-full h-72 object-cover transition-transform duration-500 group-hover:scale-105"
            onError={handleImageError}
          />
          <div className="absolute inset-0 bg-gradient-to-t from-gray-900/20 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300"></div>
        </a>
        <button
          className="absolute top-3 right-3 p-2 bg-white/95 backdrop-blur-sm rounded-full opacity-0 group-hover:opacity-100 transition-all duration-300 hover:bg-rose-100 shadow-sm"
          aria-label="Zur Wunschliste hinzufügen"
        >
          <Heart className="w-5 h-5 text-rose-500" />
        </button>
        {product.price && (
          <div className="absolute bottom-3 left-3 bg-gradient-to-r from-teal-500 to-teal-600 text-white px-3 py-1 rounded-full shadow-sm">
            <span className="font-medium" dangerouslySetInnerHTML={{ __html: product.price }} />
          </div>
        )}
      </div>
      <div className="p-5">
        <h3 className="text-lg font-semibold mb-3 text-gray-800 line-clamp-2">{product.name}</h3>
        <div className="flex justify-between items-center">
          <a href={product.url} className="flex items-center text-teal-600 hover:text-teal-700 font-medium transition-colors duration-200">
            Details
            <ChevronRight className="w-4 h-4 ml-1" />
          </a>
          {(onLike || onDislike) && (
            <div className="flex items-center gap-2">
              {onLike && (
                <button
                  className="p-2 rounded-full hover:bg-teal-50 transition-colors duration-200"
                  onClick={() => onLike(product.id)}
                >
                  <ThumbsUp className={`w-5 h-5 ${likedProducts.includes(product.id) ? 'text-teal-600' : 'text-gray-400'}`} />
                </button>
              )}
              {onDislike && (
                <button
                  className="p-2 rounded-full hover:bg-rose-50 transition-colors duration-200"
                  onClick={() => onDislike(product.id)}
                >
                  <ThumbsDown className="w-5 h-5 text-gray-400" />
                </button>
              )}
            </div>
          )}
          <a
            rel="nofollow"
            target="_blank"
            onClick={() => window._paq?.push(['trackEvent', 'Conversion', 'Klick zum Shop', 'Teaser'])}
            href={`/redirect.php?product=${product.slug}`}
            className="px-4 py-2 bg-gradient-to-r from-teal-500 to-teal-600 text-white rounded-full hover:from-teal-600 hover:to-teal-700 hover:shadow-lg transition-all duration-300"
          >
            <span className="text-sm font-medium">{shopButtonText}</span>
          </a>
        </div>
      </div>
    </div>
  );
});

// ProductGrid Komponente – angepasst für 2 Spalten auf Mobil und 4 auf Desktop
const ProductGrid = React.memo(({ products, loading, error, onLike, onDislike, likedProducts }) => {
  if (loading) return (
    <div className="flex flex-col items-center py-16">
      <Loader2 className="w-10 h-10 text-teal-600 animate-spin" />
      <span className="mt-4 text-gray-700 text-lg font-medium">Geschenke werden geladen...</span>
    </div>
  );
  if (error) return <Alert>{error}</Alert>;
  if (!products?.length) return (
    <div className="text-center py-16">
      <Package className="w-16 h-16 text-gray-300 mx-auto mb-4" />
      <p className="text-gray-600 text-lg font-medium">Keine Geschenke gefunden</p>
    </div>
  );

  return (
    <div className="grid grid-cols-2 sm:grid-cols-2 lg:grid-cols-4 gap-6">
      {products.map(p => (
        <ProductCard
          key={p.id}
          product={p}
          onLike={onLike}
          onDislike={onDislike}
          likedProducts={likedProducts}
        />
      ))}
    </div>
  );
});

