// Haupt-Komponente
const UnifiedCard = ({ mode = 'category' }) => {
  const [state, setState] = useState({
    contentId: null,
    popularProducts: [],
    popularOffset: 0,
    newProducts: [],
    newOffset: 0,
    randomProducts: [],
    risingProducts: [],
    sixMonthsPopular: [],
    filteredProducts: [],
    filteredOffset: 0,
    loadingPopular: false,
    loadingNew: false,
    loadingRandom: false,
    loadingRising: false,
    loadingSixMonths: false,
    loadingFiltered: false,
    errorPopular: null,
    errorNew: null,
    errorRandom: null,
    errorRising: null,
    errorSixMonths: null,
    errorFiltered: null,
    filterSectionOpen: false,
    activeFilters: {},
    likedProducts: typeof window !== 'undefined' ? JSON.parse(localStorage.getItem('likedProducts') || '[]') : [],
    dislikedProducts: [],
    contentDetails: null,
    showRandomModule: false
  });

  const idKey = mode === 'category' ? 'category_id' : 'tag_id';
  const randomAction = mode === 'category' ? 'wcc_get_random_products_from_category' : 'wcc_get_random_products_from_tag';
  const detailsAction = mode === 'category' ? 'wcc_get_category_details' : 'wcc_get_tag_details';

  const ajaxFetch = useCallback(async (action, data = {}) => {
    const formData = new FormData();
    formData.append('action', action);
    if (window.wcc_ajax?.nonce) formData.append('nonce', window.wcc_ajax.nonce);
    Object.entries(data).forEach(([key, value]) => formData.append(key, value));

    const response = await fetch(window.wcc_ajax.ajax_url, {
      method: 'POST',
      body: formData,
      credentials: 'same-origin'
    });
    const json = await response.json();
    if (!json.success) throw new Error(json.data || 'Unbekannter Fehler');
    return json.data;
  }, []);

  const updateState = useCallback((updates) => {
    setState(prev => ({ ...prev, ...updates }));
  }, []);

  const loadProducts = useCallback(async (type, append = false) => {
    const config = {
      popular: {
        action: 'wcc_load_more_popular_products',
        setter: 'popularProducts',
        offset: 'popularOffset',
        loading: 'loadingPopular',
        error: 'errorPopular'
      },
      new: {
        action: 'wcc_load_more_new_products',
        setter: 'newProducts',
        offset: 'newOffset',
        loading: 'loadingNew',
        error: 'errorNew'
      },
      rising: {
        action: 'wcc_load_more_rising_products',
        setter: 'risingProducts',
        offset: 'risingProducts.length',
        loading: 'loadingRising',
        error: 'errorRising'
      },
      sixMonths: {
        action: 'wcc_load_more_six_months_popular_products',
        setter: 'sixMonthsPopular',
        offset: null,
        loading: 'loadingSixMonths',
        error: 'errorSixMonths'
      },
      filtered: {
        action: 'wcc_filter_products',
        setter: 'filteredProducts',
        offset: 'filteredOffset',
        loading: 'loadingFiltered',
        error: 'errorFiltered'
      }
    };

    const { action, setter, offset, loading, error } = config[type];
    updateState({ [loading]: true, [error]: null });

    try {
      const params = {
        [idKey]: state.contentId,
        limit: type === 'sixMonths' ? 4 : 12,
        ...(type === 'filtered' && { filters: JSON.stringify(state.activeFilters) }),
        ...(offset && { offset: append ? state[offset] : 0 })
      };
      const data = await ajaxFetch(action, params);

      updateState({
        [setter]: append ? [...state[setter], ...data] : data,
        ...(offset && { [offset]: append ? state[offset] + data.length : data.length }),
        [loading]: false
      });
    } catch (err) {
      updateState({ [error]: err.message, [loading]: false });
    }
  }, [state.contentId, state.activeFilters, ajaxFetch, idKey]);

  const loadRandomProducts = useCallback(async () => {
    updateState({ loadingRandom: true, errorRandom: null });
    try {
      const data = await ajaxFetch(randomAction, {
        [idKey]: state.contentId,
        count: 12,
        exclude: [...state.likedProducts, ...state.dislikedProducts]
      });
      updateState({ randomProducts: data, loadingRandom: false });
    } catch (err) {
      updateState({ errorRandom: err.message, loadingRandom: false });
    }
  }, [state.contentId, state.likedProducts, state.dislikedProducts, ajaxFetch, randomAction, idKey]);

  const handleRemoveRandomProduct = useCallback(async (productId) => {
    try {
      await ajaxFetch('wcc_record_product_feedback', {
        product_id: productId,
        [idKey]: state.contentId,
        feedback_type: 'dislike'
      });

      const remainingProducts = state.randomProducts.filter(p => p.id !== productId);
      const newData = await ajaxFetch(randomAction, {
        [idKey]: state.contentId,
        count: 1,
        exclude: [
          ...state.likedProducts,
          ...state.dislikedProducts,
          ...remainingProducts.map(p => p.id)
        ]
      });

      updateState({
        randomProducts: [...remainingProducts, ...(newData || [])]
      });
    } catch (err) {
      alert(`Fehler beim Entfernen des Produkts: ${err.message}`);
    }
  }, [state.contentId, state.randomProducts, state.likedProducts, state.dislikedProducts, ajaxFetch, randomAction, idKey]);

  const toggleFilterValue = useCallback((filterName, value) => {
    updateState(prev => {
      const currentValues = prev.activeFilters[filterName] || [];
      const newValues = currentValues.includes(value)
        ? currentValues.filter(v => v !== value)
        : [...currentValues, value];

      return {
        activeFilters: {
          ...prev.activeFilters,
          [filterName]: newValues.length ? newValues : undefined
        },
        filteredOffset: 0
      };
    });
  }, []);

  const applyFilters = useCallback(debounce(() => {
    loadProducts('filtered', false);
  }, 300), [loadProducts]);

  const loadContentDetails = useCallback(async () => {
    try {
      const data = await ajaxFetch(detailsAction, { [idKey]: state.contentId });
      updateState({ contentDetails: data });
    } catch (err) {
      console.error('Error loading content details:', err);
    }
  }, [state.contentId, ajaxFetch, detailsAction, idKey]);

  useEffect(() => {
    const elementId = mode === 'category' ? 'category-card' : 'tag-card';
    const dataAttr = mode === 'category' ? 'data-category-id' : 'data-tag-id';
    const el = document.getElementById(elementId);
    if (el) {
      const id = parseInt(el.getAttribute(dataAttr), 10);
      if (id) updateState({ contentId: id });
    }
  }, [mode]);

  useEffect(() => {
    if (!state.contentId) return;

    Promise.all([
      loadProducts('popular'),
      loadProducts('new'),
      loadRandomProducts(),
      mode === 'category' && loadProducts('rising'),
      loadProducts('sixMonths'),
      loadContentDetails()
    ]).catch(console.error);
  }, [state.contentId, mode]);

  useEffect(() => {
    if (state.showRandomModule) loadRandomProducts();
  }, [state.showRandomModule]);

  return (
    <div
      className="min-h-screen bg-gradient-to-b from-teal-50 via-white to-amber-50"
      id={mode === 'category' ? 'category-card' : 'tag-card'}
      {...(mode === 'category' ? { 'data-category-id': state.contentId } : { 'data-tag-id': state.contentId })}
    >
      <main className="container mx-auto max-w-screen-xl px-4 py-12">
        {state.contentDetails && <ContentHeader data={state.contentDetails} mode={mode} />}

        <section className="mb-16">
          <SectionHeader title="Aktuell beliebt" subtitle="Die Favoriten unserer Community" icon={Heart} />
          <ProductGrid
            products={state.popularProducts}
            loading={state.loadingPopular}
            error={state.errorPopular}
            likedProducts={state.likedProducts}
          />
          {state.popularProducts.length > 0 && (
            <LoadMoreButton onClick={() => loadProducts('popular', true)} loading={state.loadingPopular} />
          )}
        </section>

        {state.contentDetails?.info?.contents && (
          <section className="mb-16">
            <div className="bg-white p-6 rounded-xl shadow-sm hover:shadow-md transition-all duration-300 border border-gray-200">
              <div className="flex items-center mb-4">
                <div className="bg-teal-100 p-3 rounded-full mr-4 shadow-sm">
                  <Gift className="w-7 h-7 text-teal-600" />
                </div>
                <h3 className="text-2xl font-semibold text-gray-800">Was dich erwartet</h3>
              </div>
              <div className="text-gray-700 text-base leading-relaxed" dangerouslySetInnerHTML={{ __html: state.contentDetails.info.contents }} />
            </div>
          </section>
        )}

        <section className="mb-16">
          <SectionHeader title="Frische Ideen" subtitle="Neueste Geschenk-Inspirationen" icon={Gift} />
          <ProductGrid
            products={state.newProducts}
            loading={state.loadingNew}
            error={state.errorNew}
            likedProducts={state.likedProducts}
          />
          {state.newProducts.length > 0 && (
            <LoadMoreButton onClick={() => loadProducts('new', true)} loading={state.loadingNew} />
          )}
        </section>

        {mode === 'category' && (
          <section className="mb-16">
            <SectionHeader title="Aufsteiger" subtitle="Heute besonders gefragt" icon={ThumbsUp} />
            <ProductGrid
              products={state.risingProducts}
              loading={state.loadingRising}
              error={state.errorRising}
              likedProducts={state.likedProducts}
            />
            {state.risingProducts.length > 0 && (
              <LoadMoreButton onClick={() => loadProducts('rising', true)} loading={state.loadingRising} />
            )}
          </section>
        )}

        <section className="mb-16">
          <SectionHeader title="Zeitlose Klassiker" subtitle="Immer eine gute Wahl" icon={Tag} />
          <ProductGrid
            products={state.sixMonthsPopular}
            loading={state.loadingSixMonths}
            error={state.errorSixMonths}
            likedProducts={state.likedProducts}
          />
        </section>

        <FilterSection
          isOpen={state.filterSectionOpen}
          onToggle={() => updateState({ filterSectionOpen: !state.filterSectionOpen })}
          activeFilters={state.activeFilters}
          onToggleFilterValue={toggleFilterValue}
          onApplyFilters={applyFilters}
        />

        <section className="mb-16" id="filteredProducts">
          <SectionHeader title="Deine Auswahl" subtitle="Geschenke nach deinen Wünschen" icon={Sliders} />
          <ProductGrid
            products={state.filteredProducts}
            loading={state.loadingFiltered}
            error={state.errorFiltered}
            likedProducts={state.likedProducts}
          />
          {state.filteredProducts.length > 0 && (
            <LoadMoreButton onClick={() => loadProducts('filtered', true)} loading={state.loadingFiltered} />
          )}
        </section>

        {(state.contentDetails?.info?.target_audience ||
          state.contentDetails?.info?.age_group ||
          state.contentDetails?.info?.special_features) && (
          <section className="mb-16">
            <SectionHeader title="Mehr erfahren" subtitle="Alles, was du wissen musst" icon={Tag} />
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              {state.contentDetails.info.target_audience && (
                <div className="bg-white rounded-xl shadow-sm p-6 hover:shadow-md transition-all duration-300 border border-gray-200">
                  <div className="flex items-center mb-4">
                    <div className="bg-teal-100 p-3 rounded-full mr-4 shadow-sm">
                      <Heart className="w-7 h-7 text-teal-600" />
                    </div>
                    <h3 className="text-xl font-semibold text-gray-800">Für wen?</h3>
                  </div>
                  <div className="text-gray-700 text-base leading-relaxed" dangerouslySetInnerHTML={{ __html: state.contentDetails.info.target_audience }} />
                </div>
              )}
              {state.contentDetails.info.age_group && (
                <div className="bg-white rounded-xl shadow-sm p-6 hover:shadow-md transition-all duration-300 border border-amber-200">
                  <div className="flex items-center mb-4">
                    <div className="bg-amber-100 p-3 rounded-full mr-4 shadow-sm">
                      <Tag className="w-7 h-7 text-amber-600" />
                    </div>
                    <h3 className="text-xl font-semibold text-gray-800">Alter</h3>
                  </div>
                  <div className="text-gray-700 text-base leading-relaxed" dangerouslySetInnerHTML={{ __html: state.contentDetails.info.age_group }} />
                </div>
              )}
              {state.contentDetails.info.special_features && (
                <div className="bg-white rounded-xl shadow-sm p-6 hover:shadow-md transition-all duration-300 border border-rose-200">
                  <div className="flex items-center mb-4">
                    <div className="bg-rose-100 p-3 rounded-full mr-4 shadow-sm">
                      <Gift className="w-7 h-7 text-rose-600" />
                    </div>
                    <h3 className="text-xl font-semibold text-gray-800">Besonderheiten</h3>
                  </div>
                  <div className="text-gray-700 text-base leading-relaxed" dangerouslySetInnerHTML={{ __html: state.contentDetails.info.special_features }} />
                </div>
              )}
            </div>
          </section>
        )}

        <section className="mb-16">
          {!state.showRandomModule ? (
            <div
              className="bg-gradient-to-r from-teal-50 to-amber-50 rounded-xl shadow-sm p-8 text-center cursor-pointer hover:shadow-md transition-all duration-300"
              onClick={() => updateState({ showRandomModule: true })}
            >
              <div className="flex justify-center mb-4">
                <Gift className="w-12 h-12 text-teal-600" />
              </div>
              <p className="text-xl font-semibold text-gray-800">
                Lass dich überraschen mit zufälligen Ideen
              </p>
            </div>
          ) : (
            <>
              <div className="flex justify-between items-center mb-6">
                <h2 className="text-3xl font-bold text-gray-900 bg-gradient-to-r from-teal-600 to-amber-500 bg-clip-text text-transparent">Überraschungen</h2>
                <button
                  onClick={() => updateState({ showRandomModule: false })}
                  className="text-teal-600 hover:text-teal-800 transition-colors duration-200"
                  aria-label="Modul schließen"
                >
                  <X className="w-7 h-7" />
                </button>
              </div>
              <ProductGrid
                products={state.randomProducts}
                loading={state.loadingRandom}
                error={state.errorRandom}
                onDislike={handleRemoveRandomProduct}
                likedProducts={state.likedProducts}
              />
            </>
          )}
        </section>

        {state.contentDetails && <ContentFooterDetails data={state.contentDetails} />}
      </main>
    </div>
  );
};

export default UnifiedCard;
